<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import TextFormatting from './TextFormatting.vue';
import {fuzzyMatch} from '../../shared/search.mjs';
import {computed,ref,watch} from 'vue';import {X,Upload,Trash2,Download,WandSparkles} from 'lucide-vue-next';
import {useStudio,api} from '../store';import {bubblePresets,textPresets,stickerPresets} from '../editor/decorations';import BubbleShape from './BubbleShape.vue';import StickerShape from './StickerShape.vue';
const props=defineProps({kind:String,initial:Object});const emit=defineEmits(['close','choose']);const s=useStudio(),input=ref(),category=ref('全部'),query=ref(''),importing=ref(false);
const saved=s.config.decorationDrafts?.[props.kind];const draft=ref({...{shape:'ellipse',tailAngle:135,tailEnabled:true,tailLength:.5,tailWidth:24,text:'',fontFamily:'Ruoshui-notosanssc',presetId:'plain'},...(saved||{}),...(props.initial||{})});
if(!props.initial&&['在这里输入文字','在这里输入对白'].includes(draft.value.text))draft.value.text='';
if(!props.initial&&props.kind==='text'){if(!draft.value.directionSet)draft.value.vertical=draft.value.presetId==='vertical';draft.value.borderWidth=textPresets.find(p=>p.id===draft.value.presetId)?.borderWidth||0;}
watch(draft,value=>{(s.config.decorationDrafts||(s.config.decorationDrafts={}))[props.kind]={...value};},{deep:true});
const library=computed(()=>s.config.stickerLibrary||[]),categories=computed(()=>['全部',...new Set(stickerPresets.map(p=>p.category)),'我的贴纸']);
const stickers=computed(()=>[...stickerPresets,...library.value.map(p=>({...p,category:'我的贴纸'}))].filter(p=>(!p.sfx||styleFilter.value==='all'||p.style===styleFilter.value)&&(category.value==='全部'||p.category===category.value)&&fuzzyMatch(query.value,p.name,p.category,p.styleName)));
const preview=computed(()=>({...draft.value,x:0,y:0,w:210,h:110,fill:'#fff',border:'#242633',borderWidth:2}));
function chooseText(p){const content=draft.value.text;Object.assign(draft.value,{vertical:false,directionSet:false,borderWidth:0,fontWeight:400,fill:'transparent',color:'#242633',fontSize:36},p,{text:content,presetId:p.presetId||p.id});}
async function importStickers(e){importing.value=true;try{const files=[...e.target.files];const result=await s.importImages(files,{select:false});const target=s.config.stickerLibrary||(s.config.stickerLibrary=[]);for(let i=0;i<result.length;i++)target.push({id:crypto.randomUUID(),name:files[i]?.name.replace(/\.[^.]+$/,'')||'导入贴纸',image:result[i].url});category.value='我的贴纸';}catch(error){s.notify(error.message,'error');}finally{importing.value=false;e.target.value='';}}
function removeSticker(id){s.config.stickerLibrary=s.config.stickerLibrary.filter(p=>p.id!==id);}
const processing=ref(''),styleFilter=ref('ink');
async function transparent(p){processing.value=p.id;try{let imageId=p.image?.split('/api/files/')[1];if(!imageId){const blob=await(await fetch(p.image)).blob();imageId=(await s.importImages([new File([blob],'贴纸原图.png',{type:blob.type})],{select:false}))[0].id;}const result=await api('images/cutout',{imageId,mode:'auto'});const item=library.value.find(item=>item.id===p.id);if(item){item.image=result.url;item.transparent=true;}s.notify('已生成透明底贴纸，可直接加入画布');}finally{processing.value='';}}
async function exportTransparent(p,event){
 const svg=event.currentTarget.closest('.sticker-preset').querySelector('svg').cloneNode(true);svg.setAttribute('width','768');svg.setAttribute('height','768');svg.setAttribute('xmlns','http://www.w3.org/2000/svg');
 const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));await image.decode();const canvas=document.createElement('canvas');canvas.width=768;canvas.height=768;canvas.getContext('2d').drawImage(image,0,0,768,768);await s.exportFile(p.name+'.png',await new Promise(resolve=>canvas.toBlob(resolve,'image/png')));
}
</script>
<template><div class="modal-backdrop" @click.self="initial&&kind!=='sticker'?emit('choose',draft):emit('close')" @keydown.esc="emit('close')"><section class="modal decoration-picker" role="dialog" aria-modal="true" :aria-label="ui({bubble:'选择对话框',text:'选择文本样式',sticker:'选择漫画贴纸'}[kind])"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭选择面板&quot;)" @click="emit('close')"><X/></button></div><div class="modal-title"><h2>{{ui({bubble:'选择对话框',text:'选择文本样式',sticker:'漫画贴纸库'}[kind])}}</h2></div>
 <template v-if="kind==='bubble'"><div class="preset-grid"><button v-for="p in bubblePresets" :class="['preset-tile',{selected:draft.shape===p.id}]" @click="draft.shape=p.id;draft.tailEnabled=p.id!=='rect'"><svg viewBox="-8 -8 226 160"><BubbleShape :object="{...preview,shape:p.id,tailEnabled:p.id!=='rect'}"/></svg><span>{{p.name}}</span></button></div><TextFormatting :model="draft"/><label>{{ui("对白内容")}}<textarea v-model="draft.text" :placeholder="ui(&quot;在这里输入对白&quot;)" :style="{fontFamily:draft.fontFamily}" rows="2"/></label><div class="picker-settings"><label>{{ui("尾巴方向")}}<select v-model.number="draft.tailAngle"><option v-for="p in [{a:0,n:'向右'},{a:45,n:'右下'},{a:90,n:'向下'},{a:135,n:'左下'},{a:180,n:'向左'},{a:225,n:'左上'},{a:270,n:'向上'},{a:315,n:'右上'}]" :value="p.a">{{ui(p.n)}}</option></select></label><label>{{ui("尾巴角度")}}<input type="number" v-model.number="draft.tailAngle" min="0" max="360"/></label><label class="inline-check"><input type="checkbox" v-model="draft.tailEnabled"/>{{ui("显示尾巴")}}</label></div><p class="muted">{{ui("添加后拖动四角调整尺寸；拖动橙色圆点调整尾巴方向和长度。")}}</p><button class="primary" :disabled="!draft.text.trim()" @click="emit('choose',draft)">{{ui(initial?'应用对话框样式':'添加到画布')}}</button></template>
 <template v-else-if="kind==='text'"><div class="preset-grid text-preset-grid"><button v-for="p in textPresets" :class="['preset-tile',{selected:draft.presetId===p.id}]" @click="chooseText(p)"><span :style="{background:p.fill,color:p.color,fontWeight:p.fontWeight||400,fontFamily:draft.fontFamily}">{{p.text}}</span><small>{{p.name}}</small></button></div><TextFormatting :model="draft"/><label>{{ui("文本内容")}}<textarea v-model="draft.text" :placeholder="ui(textPresets.find(p=>p.id===draft.presetId)?.text||'在这里输入文字')" :style="{fontFamily:draft.fontFamily}" rows="3"/></label><button class="primary" @click="emit('choose',draft)">{{ui(initial?'应用文本样式':'添加到画布')}}</button></template>
 <template v-else><div class="button-row"><input v-model="query" :aria-label="ui(&quot;搜索漫画贴纸&quot;)" :placeholder="ui(&quot;模糊搜索贴纸：心形、蹭蹭、拥抱、ぱん&quot;)"/><button class="secondary" @click="input.click()" :disabled="importing"><Upload :size="16"/>{{ui(importing?'正在导入…':'导入并保存贴纸')}}</button></div><label class="sticker-style-filter">{{ui("拟声字样式")}}<select v-model="styleFilter"><option value="ink">{{ui("黑字白描边")}}</option><option value="outline">{{ui("白字黑描边")}}</option><option value="vertical">{{ui("竖排")}}</option><option value="all">{{ui("显示全部款式")}}</option></select></label><div class="category-tabs"><button v-for="c in categories" :class="{active:category===c}" @click="category=c">{{ui(c)}}</button></div><div class="sticker-preset-grid"><div v-for="p in stickers" :key="p.id" class="sticker-preset checker"><button @click="emit('choose',{...p,presetId:p.presetId||p.id})" :title="ui('添加')+p.name"><StickerShape :id="p.presetId||p.id" :image="p.image"/><span>{{p.name}}</span><small v-if="p.styleName">{{ui(p.styleName)}}</small></button><div class="sticker-actions"><button v-if="!p.image" class="icon-button" :aria-label="ui('导出透明 PNG ')+p.name" :title="ui(&quot;导出透明 PNG&quot;)" @click="s.action(()=>exportTransparent(p,$event))"><Download :size="14"/></button><button v-if="p.image" class="icon-button" :disabled="!!processing" :aria-label="ui('一键生成透明底 ')+p.name" :title="ui(&quot;一键生成透明底&quot;)" @click="s.action(()=>transparent(p))"><WandSparkles :size="14" :class="{spin:processing===p.id}"/></button><button v-if="p.category==='我的贴纸'" class="icon-button danger" :title="ui('从贴纸库移除')+p.name" @click="removeSticker(p.id)"><Trash2 :size="14"/></button></div></div></div><p v-if="!stickers.length" class="empty">{{ui("暂无贴纸。可以导入 PNG、JPG 或 WebP；透明 PNG 适合做贴纸。")}}</p><p class="muted">{{ui("内置 ")}}{{ui(stickerPresets.length)}}{{ui(" 种透明底矢量贴纸，含日漫拟声字、爱心、速度线和情绪符号。内置贴纸可直接导出透明 PNG，导入图片可一键去除背景。导入的贴纸保存在 works，可反复添加；从库中移除不影响画布上已添加的贴纸。")}}</p><input ref="input" type="file" multiple accept="image/png,image/jpeg,image/webp" class="hidden" @change="importStickers"/></template>
 </section></div></template>
